import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"模拟器冲击模型","description":"","frontmatter":{"title":"模拟器冲击模型","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/simulator-impact-bias.md","filePath":"quant/simulator-impact-bias.md","lastUpdated":1789023840000}'),E={name:"quant/simulator-impact-bias.md"};function m(B,a,A,c,u,_){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="模拟器冲击模型" tabindex="-1">模拟器冲击模型 <a class="header-anchor" href="#模拟器冲击模型" aria-label="Permalink to &quot;模拟器冲击模型&quot;">​</a></h1><div class="epigraph"><p>强化学习会去采集模拟器里被写错的那一项。若冲击太弱，智能体学会瞬时吃完；若冲击可被来回交易套利，智能体学会做自己的做市商。</p><footer>—— 据 Gatheral 对冲击模型无动态套利的要求；对照 Almgren–Chriss 把临时与永久冲击分开的设定</footer></div><p><a href="/quant/pomdp-fills">部分可观测与延迟成交</a>处理了观测与回报。<a href="/quant/sim-to-real-trading">模拟器偏差</a>已经列出成交假设从松到紧的阶梯。本课的缺口是专门针对 <strong>RL 训练用的冲击模块</strong>：它如何把偏差写进政策，以及哪些函数形式会制造虚假最优。强化学习课序在本课收束。不重写 Almgren–Chriss 的最优轨迹推导，只要求模拟器里的冲击满足：对自己的量有弹性、临时项衰减、永久项不提供免费午餐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RL 的环境就是模拟器。冲击函数 \\(I(q,\\mathrm{state})\\) 若恒为零，最优是立刻成交，延迟预算与容量课的全部权衡消失。若只有与量无关的常数滑点，智能体不会学会避开浅簿，只会学会少交易——或在奖励塑造下学会把交易藏进标记噪声。若永久冲击非线性且允许来回交易抽取，Gatheral 意义上的动态套利出现，政策会在模拟器里印钞。缺口是把冲击模块当成必须验证的生产模型，写入<a href="/quant/model-risk-inventory">模型风险清单</a>，而不是当成训练超参。</p><p>自己的历史 TCA 校准是局部弹性，拥挤课时已警告。RL 若用该局部弹性去优化比历史更大的 \\(q\\)，是在外推。必须对参与率凸化，或硬限制动作使 \\(q\\) 不超过校准支撑。</p><h3 id="临时、永久、以及「别人的反应」" tabindex="-1">临时、永久、以及「别人的反应」 <a class="header-anchor" href="#临时、永久、以及「别人的反应」" aria-label="Permalink to &quot;临时、永久、以及「别人的反应」&quot;">​</a></h3><p>临时冲击：吃完后簿恢复一部分，衰减时间应短于回合。永久冲击：中点留下一截，进入随后观测，这才能让 POMDP 的 \\(o\\) 含有自己的痕迹。缺第三项「别人的反应」（撤单、跟风）时，限价的填成概率仍偏乐观。本课不要求建一个完整代理人市场，但要求：至少临时+永久；并报告在没有反应项时填成上界。乐观界不能单独部署。</p><p><span class="marginnote">集合竞价的冲击不是连续速率的积分。模拟器必须在拍卖段换成批量出清，否则 RL 会学到在开盘用连续吃单去「优化」一个不存在的轨迹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>冲击模块接口：输入本步成交量、方向、当时深度或 ADV、协议类型；输出临时成本、永久中点位移、以及可选的深度消耗。校验：无交易时价格路径与历史一致（或一致的统计）；小量时成本接近有效价差；来回交易不能产生正期望；参与率升高时成本凸。把 RL 关掉，用固定 POV 走一遍，成本应与 TCA 同量级。</p><p>训练时对冲击参数做敏感性：\\(\\Lambda\\) 放大 50%，政策应变得更慢。若政策不变，说明奖励没接到冲击，或动作根本走不到约束。这是单元测试。sim-to-real：小规模真单的实现缺口应落在模拟器压力参数下的区间内，而不是落在最乐观参数上。</p><h3 id="冲击偏差如何表现为「假-alpha」" tabindex="-1">冲击偏差如何表现为「假 alpha」 <a class="header-anchor" href="#冲击偏差如何表现为「假-alpha」" aria-label="Permalink to &quot;冲击偏差如何表现为「假 alpha」&quot;">​</a></h3><p>冲击过弱 → 政策过激进 → 实盘缺口爆炸。冲击过强且不可套利 → 政策过保守，看起来像失败的 RL，其实是校准。可套利冲击 → 政策在模拟器里高夏普，实盘接近零或为负。第三种最危险，因为研究会过关。检查来回交易期望是上线门槛。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RL 优化的是模拟器测度下的值函数。冲击函数定义了动作如何改写随后状态与奖励。偏置的 \\(I\\) 等于偏置的 \\(P\\) 与 \\(R\\)。POMDP 滤波再好，滤的也是错的生成过程。这与另类数据回填同构：环境被事后改写成更好交易的世界。纠正办法同样是 vintage：冲击参数用更早的样本校准，在更晚的样本上做策略评估，且评估环境不得弱于训练环境。</p><p><span class="marginnote">不要把经验 <a href="/quant/kyle-lambda">Kyle lambda</a> 直接当永久冲击塞进模拟器。lambda 含信息，执行冲击应尽量是机械的。混用会让智能体学会「不要与知情者成交」——它没有这个观测。</span></p>',17)),(e(),s(h,null,{default:r(()=>[p(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TB%0A%20%20A%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E5%90%83%E6%88%96%E6%8C%82%22%5D%20--%3E%20I%5B%22%E5%86%B2%E5%87%BB%E6%A8%A1%E5%9D%97%22%5D%0A%20%20I%20--%3E%20TMP%5B%22%E4%B8%B4%E6%97%B6%E6%88%90%E6%9C%AC%22%5D%0A%20%20I%20--%3E%20PER%5B%22%E6%B0%B8%E4%B9%85%E4%B8%AD%E7%82%B9%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20PER%20--%3E%20O%5B%22%E4%B8%8B%E4%B8%80%E8%A7%82%E6%B5%8B%E5%90%AB%E8%87%AA%E5%B7%B1%E7%9A%84%E7%97%95%E8%BF%B9%22%5D%0A%20%20TMP%20--%3E%20R%5B%22%E5%A5%96%E5%8A%B1%22%5D%0A%20%20ARB%5B%22%E6%9D%A5%E5%9B%9E%E4%BA%A4%E6%98%93%E6%9C%9F%E6%9C%9B%22%5D%20--%3E%20G%5B%22%E5%BF%85%E9%A1%BB%20%E2%89%A40%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="评估环境不得弱于训练环境" tabindex="-1">评估环境不得弱于训练环境 <a class="header-anchor" href="#评估环境不得弱于训练环境" aria-label="Permalink to &quot;评估环境不得弱于训练环境&quot;">​</a></h3><p>训练用凸冲击、评估用零冲击，政策会看起来稳健，其实没有经过更严的世界。应反过来：评估用压力参数，训练用基准参数，过关再收紧训练。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>真实市场的冲击有非线性、有公告状态、有拍卖。任何参数化都是错的，目标是偏差方向已知、对部署保守。多智能体模拟超出本课。加密链上冲击是 AMM 曲线或订单簿，函数形式不同，但无套利检查同样适用。</p><p><span class="marginnote">经验 Kyle lambda 含信息，不宜直接当永久冲击。执行冲击应尽量机械；否则智能体被要求躲开它看不见的知情者。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RL 会采集冲击函数的错误；冲击是生产模型，要进清单。</li><li>至少临时+永久；来回交易期望必须非正。</li><li>校准支撑外的量必须凸化或截断动作。</li><li>拍卖段不得用连续冲击。</li><li>评估环境不得弱于训练环境；真单缺口对照压力参数。</li><li>出处：Almgren and Chriss；Gatheral 对冲击与无动态套利；sim-to-real 见 Lopez de Prado 对回测路径依赖的讨论；经验冲击见 Cont, Kukanov and Stoikov。</li></ul>',7))])}const f=i(E,[["render",m]]);export{b as __pageData,f as default};
